import{_ as e,o,c as t,a2 as s}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"启动模式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/boot-modes.md","filePath":"zh/manual/boot-modes.md"}'),i={name:"zh/manual/boot-modes.md"};function l(n,a,d,c,p,r){return o(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="启动模式" tabindex="-1">启动模式 <a class="header-anchor" href="#启动模式" aria-label="Permalink to &quot;启动模式&quot;">​</a></h1><h2 id="bios-传统" tabindex="-1">BIOS（传统） <a class="header-anchor" href="#bios-传统" aria-label="Permalink to &quot;BIOS（传统）&quot;">​</a></h2><p>默认方式：从 ISO 引导 GRUB i386-pc，加载 multiboot2 内核及其内嵌模块链。<code>install</code> / <code>abdisk</code> 写入磁盘的正是同一个加载器，因此已安装系统的引导方式与其来源 ISO 完全一致。</p><h2 id="uefi" tabindex="-1">UEFI <a class="header-anchor" href="#uefi" aria-label="Permalink to &quot;UEFI&quot;">​</a></h2><p>ISO 自带一条 EFI 启动分支；在 QEMU 下用 OVMF 引导它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512M -bios OVMF.fd -cdrom opencube-3.0.0.iso \\</span></span>
<span class="line"><span>    -boot d</span></span></code></pre></div><p>在真实硬件上，于固件启动菜单中选择 EFI 项。A/B 槽位逻辑（见下文）在两种模式下完全相同。</p><h2 id="a-b-槽位菜单" tabindex="-1">A/B 槽位菜单 <a class="header-anchor" href="#a-b-槽位菜单" aria-label="Permalink to &quot;A/B 槽位菜单&quot;">​</a></h2><p>在 A/B 盘上，GRUB 读取启动标志并提供：</p><ul><li><strong>活动槽位</strong>（默认，自动选中）；</li><li><strong>强制槽位 A</strong> 与<strong>强制槽位 B</strong> 项——活动槽位表现异常时的手动覆盖手段。</li></ul><p>标志保存在 A/B 盘上；<code>update status</code> 显示哪个槽位正在运行、哪个槽位下次启动，<code>update rollback</code> 可在系统内部将其翻转。</p><h2 id="持久化" tabindex="-1">持久化 <a class="header-anchor" href="#持久化" aria-label="Permalink to &quot;持久化&quot;">​</a></h2><p>ISO 引导的系统从 RAM 运行：重启后一切重置。要获得持久化的系统：</p><ol><li><code>install &lt;disk&gt;</code>——分区 + 复制当前运行的内核 + GRUB + /etc 卷，单系统形态；或</li><li><code>abdisk &lt;disk&gt;</code>（通过 <code>disk-tool</code> 的 A/B 管理器）——双槽位更新盘形态，OTA 更新以它为目标。</li></ol><p>挂载一个配置卷（<code>etc.img</code>，一块包含 <code>opencube.conf</code> 与可选 <code>ssh_host_key</code> 的 FAT32 磁盘），即可在不安装的情况下跨重启携带设置与主机密钥。</p><h2 id="启动自检" tabindex="-1">启动自检 <a class="header-anchor" href="#启动自检" aria-label="Permalink to &quot;启动自检&quot;">​</a></h2><p>每次引导都会在 shell 之前运行自检链：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>exception self-test: 3/3</span></span>
<span class="line"><span>boot complete....... OK</span></span></code></pre></div><p>一次到达 <code>ush&gt;</code> 的引导，已经证明了它的异常栈、定时器和控制台。回归门禁会断言这些相同的输出行，外加一次实时帧缓冲检查（BUG #66）——所以&quot;它启动成功了&quot;是一句经过测试的陈述，而不是一个愿望。</p>`,19)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
